CID = 'numpy2'
VEC, BROAD, STATS, IDX, AXIS, MASK, VIEW, SORT = "Vectorisation: maths on the whole array", "Broadcasting", "Statistics", "Indexing and slicing", "axis: the most confusing argument in NumPy", "Filtering with boolean masks", "Views vs copies", "Sorting and unique values"
def W(lv, sec, q, starter, sol, e): return dict(lv=lv, ty='code', sec=sec, q=q, starter=starter, sol=sol, e=e)
def F(lv, sec, q, c, fixed, e): return dict(lv=lv, ty='fix', sec=sec, q=q, c=c, fixed=fixed, e=e)
def T(lv, sec, c, e): return dict(lv=lv, ty='type', sec=sec, q="Type exactly what this code prints.", c=c, e=e)
NP = 'import numpy as np\n'
SM = 'sales = np.array([[100, 150, 200],\n                  [120, 140, 180],\n                  [110, 160, 220]])\n'
Q = [
 # ---------- Basic ----------
 T(1, VEC, NP + 'prices = np.array([10, 20, 30])\nprint(prices * 2, prices + 5)', "Maths on an array is done on every value at once: no loop needed."),
 W(1, VEC, '`price = np.array([120, 45, 80])` and `qty = np.array([2, 10, 3])`. Print the revenue of each item, then the total revenue.', NP + 'price = np.array([120, 45, 80])\nqty = np.array([2, 10, 3])\n', NP + 'price = np.array([120, 45, 80])\nqty = np.array([2, 10, 3])\nrevenue = price * qty\nprint(revenue)\nprint(revenue.sum())', "Two arrays of the same length are multiplied position by position."),
 W(1, STATS, '`sales = np.array([12000, 15000, 18000, 14000])`. Print the mean, the highest and the lowest value with one `print()`.', NP + 'sales = np.array([12000, 15000, 18000, 14000])\n', NP + 'sales = np.array([12000, 15000, 18000, 14000])\nprint(sales.mean(), sales.max(), sales.min())', "Arrays have built-in statistics methods. `mean()` always gives a float."),
 W(1, IDX, '`rev = np.array([50000, 65000, 72000, 58000])`. Print the first value, the last value, and the middle two (a slice), with one `print()`.', NP + 'rev = np.array([50000, 65000, 72000, 58000])\n', NP + 'rev = np.array([50000, 65000, 72000, 58000])\nprint(rev[0], rev[-1], rev[1:3])', "Indexing and slicing work like lists. A slice of an array is an array."),
 W(1, MASK, '`salaries = np.array([45000, 55000, 38000, 72000])`. Print the salaries above 50000, using a boolean mask.', NP + 'salaries = np.array([45000, 55000, 38000, 72000])\n', NP + 'salaries = np.array([45000, 55000, 38000, 72000])\nprint(salaries[salaries > 50000])', "`salaries > 50000` is an array of `True`/`False`. Putting it inside `[ ]` keeps only the `True` positions."),
 F(1, MASK, "This code should print `[45000 55000]`, but it crashes. Fix the mask.", NP + 'sal = np.array([45000, 55000, 38000])\nprint(sal[sal > 40000 and sal < 60000])', NP + 'sal = np.array([45000, 55000, 38000])\nprint(sal[(sal > 40000) & (sal < 60000)])', "For arrays, use `&` (and) and `|` (or), with brackets around each comparison. `and` only works on single True/False values."),
 T(1, AXIS, NP + 'm = np.array([[1, 2], [3, 4], [5, 6]])\nprint(m.sum(axis=0), m.sum(axis=1))', "`axis=0` goes down the rows, giving one total per column. `axis=1` goes across, giving one total per row."),
 F(1, VEC, "This code should double every price and print `[20 40 60]`. Fix it.", 'prices = [10, 20, 30]\nprint(prices * 2)', NP + 'prices = np.array([10, 20, 30])\nprint(prices * 2)', "A list times 2 repeats the list. A NumPy array times 2 doubles every value."),
 # ---------- Medium ----------
 W(2, BROAD, '`m = np.array([[1, 2, 3], [4, 5, 6]])`. Add `[10, 20, 30]` to every row using broadcasting, and print the result.', NP + 'm = np.array([[1, 2, 3], [4, 5, 6]])\n', NP + 'm = np.array([[1, 2, 3], [4, 5, 6]])\nprint(m + np.array([10, 20, 30]))', "A row with the same number of columns is \"stretched\" over every row of the table."),
 W(2, AXIS, 'Rows are months and columns are products. Print the total per month, then the total per product.', NP + SM, NP + SM + 'print(sales.sum(axis=1))\nprint(sales.sum(axis=0))', "One total per row (month) is `axis=1`. One total per column (product) is `axis=0`."),
 T(2, STATS, NP + 'a = np.array([2, 4, 4, 4, 5, 5, 7, 9])\nprint(a.mean(), a.std(), np.median(a))', "The mean is 40 / 8 = 5.0. The standard deviation of this classic example is exactly 2.0. The median averages the two middle values, 4 and 5."),
 W(2, MASK, '`marks = np.array([45, 82, 30, 67])`. Use `np.where` to label each mark `Pass` (35 or more) or `Fail`, and print the labels.', NP + 'marks = np.array([45, 82, 30, 67])\n', NP + 'marks = np.array([45, 82, 30, 67])\nprint(np.where(marks >= 35, "Pass", "Fail"))', "`np.where(condition, if_true, if_false)` is a vectorised if/else."),
 W(2, IDX, 'Rows are January to March, columns are products 1 to 3. Print the February row, then the column of product 3, then the March value of product 2.', NP + SM, NP + SM + 'print(sales[1])\nprint(sales[:, 2])\nprint(sales[2, 1])', "`[row, column]`. A `:` means \"all\", so `[:, 2]` is the whole third column."),
 F(2, AXIS, "This code should print the total per month (per row): `[250 260]`. Fix it.", NP + 'm = np.array([[100, 150], [120, 140]])\nprint(m.sum(axis=0))', NP + 'm = np.array([[100, 150], [120, 140]])\nprint(m.sum(axis=1))', "`axis=0` adds up each column. One total per row needs `axis=1`."),
 T(2, VIEW, NP + 'x = np.array([1, 2, 3, 4])\npart = x[1:3]\npart[0] = 99\nprint(x)', "A slice of an array is a **view** of the same data, so changing it changes the original too."),
 W(2, SORT, '`ratings = np.array([5, 3, 5, 4, 3, 5])`. Print the different ratings and how many times each one appears, using `np.unique` with `return_counts=True`.', NP + 'ratings = np.array([5, 3, 5, 4, 3, 5])\n', NP + 'ratings = np.array([5, 3, 5, 4, 3, 5])\nvalues, counts = np.unique(ratings, return_counts=True)\nprint(values, counts)', "`np.unique` gives the sorted different values, and with `return_counts=True` also how often each appears."),
 W(2, MASK, '`temps = np.array([31, 35, 29, 38, 33])`. Print how many days were above 32, and their average rounded to 2 decimals.', NP + 'temps = np.array([31, 35, 29, 38, 33])\n', NP + 'temps = np.array([31, 35, 29, 38, 33])\nhot = temps[temps > 32]\nprint(len(hot), round(hot.mean(), 2))', "Filter first with a mask, then use the statistics on the filtered array."),
 F(2, VIEW, "This code should leave `y` unchanged and print `[1 2 3 4]`. Fix it.", NP + 'y = np.array([1, 2, 3, 4])\nsafe = y[1:3]\nsafe[0] = 0\nprint(y)', NP + 'y = np.array([1, 2, 3, 4])\nsafe = y[1:3].copy()\nsafe[0] = 0\nprint(y)', "A slice is a view. `.copy()` makes independent data, so changes do not reach the original."),
 # ---------- Challenge (same chapter, combined) ----------
 W(3, MASK, '`price = np.array([499, 1299, 299, 899])` and `qty = np.array([10, 3, 25, 6])`. Print the position of the product with the highest revenue (`argmax`), then the share of total revenue that comes from products with above-average revenue, as a percent with 1 decimal.', NP + 'price = np.array([499, 1299, 299, 899])\nqty = np.array([10, 3, 25, 6])\n', NP + 'price = np.array([499, 1299, 299, 899])\nqty = np.array([10, 3, 25, 6])\nrevenue = price * qty\nprint(revenue.argmax())\nbig = revenue[revenue > revenue.mean()]\nprint(f"{big.sum() / revenue.sum() * 100:.1f}%")', "Vectorise (`price * qty`), then summarise (`argmax`, `mean`), then filter with a mask: three NumPy steps in a few lines."),
 W(3, AXIS, 'Occupancy in % for 3 hotels (rows) over 4 weeks (columns): `occ = np.array([[60, 72, 75, 80], [55, 65, 70, 90], [70, 68, 74, 76]])`. Print each hotel\'s average (rounded to 2 decimals), then the number of the best week (1 to 4) by average occupancy.', NP + 'occ = np.array([[60, 72, 75, 80], [55, 65, 70, 90], [70, 68, 74, 76]])\n', NP + 'occ = np.array([[60, 72, 75, 80], [55, 65, 70, 90], [70, 68, 74, 76]])\nprint(occ.mean(axis=1).round(2))\nprint(occ.mean(axis=0).argmax() + 1)', "`axis=1` averages each hotel across weeks; `axis=0` averages each week across hotels. `argmax` counts from 0, so add 1."),
 W(3, BROAD, 'Prices of 3 products: `prices = np.array([100, 250, 400])`. Make a table with one row per discount level, using a column of factors `[[1.0], [0.9], [0.8]]` (no discount, 10% off, 20% off) and broadcasting. Print the table.', NP + 'prices = np.array([100, 250, 400])\n', NP + 'prices = np.array([100, 250, 400])\nfactors = np.array([[1.0], [0.9], [0.8]])\nprint(prices * factors)', "A column (3 x 1) times a row (3) broadcasts into a 3 x 3 table: every factor times every price."),
 T(3, SORT, NP + 'scores = np.array([70, 95, 80])\nnames = np.array(["Asha", "Ravi", "Neha"])\nprint(names[np.argsort(scores)][::-1])', "`argsort` gives the positions that would sort the scores (lowest first). Using them on `names` and reversing gives the names from highest to lowest score."),
 F(3, MASK, "This code should print the values below 10 or above 20: `[ 5 25]`. Fix the mask.", NP + 'a = np.array([5, 15, 25])\nprint(a[a < 10 | a > 20])', NP + 'a = np.array([5, 15, 25])\nprint(a[(a < 10) | (a > 20)])', "`|` runs before `<` and `>`, so without brackets Python tries `10 | a` first. Put brackets around each comparison."),
 W(3, MASK, '`sal = np.array([45000, 55000, 38000, 72000, 41000, 65000])`. Cap every salary at 60000 with `np.where`. Print the capped array and its mean rounded to 2 decimals.', NP + 'sal = np.array([45000, 55000, 38000, 72000, 41000, 65000])\n', NP + 'sal = np.array([45000, 55000, 38000, 72000, 41000, 65000])\ncapped = np.where(sal > 60000, 60000, sal)\nprint(capped)\nprint(round(capped.mean(), 2))', "`np.where` can replace values: where the test is `True` use 60000, otherwise keep the salary."),
 W(3, STATS, '`scores = np.array([40, 55, 70, 85, 100])`. Scale them to the range 0 to 1 with `(x - min) / (max - min)`, and print the result.', NP + 'scores = np.array([40, 55, 70, 85, 100])\n', NP + 'scores = np.array([40, 55, 70, 85, 100])\nprint((scores - scores.min()) / (scores.max() - scores.min()))', "Min-max scaling is one vectorised line: the lowest becomes 0, the highest becomes 1."),
]
